@layer components {
  .profile-card {
    border-width: var(--shelf-borderWidth-sm);
    border-style: solid;
    border-color: var(--shelf-profileCard-borderColor-default);
    background-color: var(--shelf-profileCard-bgColor-surface);
    padding: var(--shelf-spacing-md);
  }

  .profile-card-title {
    color: var(--shelf-profileCard-fgColor-title);
    font-size: var(--shelf-fontSize-lg);
  }

  .profile-card-subtitle {
    color: var(--shelf-profileCard-fgColor-subtitle);
    font-size: var(--shelf-fontSize-sm);
  }

  /* Skeleton variant */
  .profile-card--skeleton .profile-card-title,
  .profile-card--skeleton .profile-card-subtitle {
    display: none;
  }

  .profile-card-shimmer {
    background-color: var(--shelf-profileCard-bgColor-shimmer);
    height: var(--shelf-size-shimmerHeight);
    animation: shimmer var(--shelf-motion-duration-slow) var(--shelf-motion-easing-linear) infinite;
  }

  .profile-card-shimmer--full {
    width: 100%;
  }

  .profile-card-shimmer--narrow {
    width: var(--shelf-size-shimmerNarrow);
    margin-block-start: var(--shelf-spacing-sm);
  }

  @keyframes shimmer {
    0% {
      opacity: 1;
    }
    50% {
      opacity: var(--shelf-opacity-shimmer);
    }
    100% {
      opacity: 1;
    }
  }
}
